#include "robot_name.h"

#include <random>
#include <unordered_set>

namespace robot_name {

namespace {

std::unordered_set<std::string>& used_names()
{
    static std::unordered_set<std::string> names;
    return names;
}

std::mt19937& engine()
{
    static std::mt19937 rng{std::random_device{}()};
    return rng;
}

std::string generate_name()
{
    static const char letters[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    std::uniform_int_distribution<int> letter_dist(0, 25);
    std::uniform_int_distribution<int> digit_dist(0, 999);

    std::string name;
    do {
        name = std::string{letters[letter_dist(engine())], letters[letter_dist(engine())]}
             + std::to_string(digit_dist(engine()));
    } while (!used_names().insert(name).second);
    return name;
}

}  // namespace

robot::robot() : m_name(generate_name()) {}

const std::string& robot::name() const { return m_name; }

void robot::reset() { m_name = generate_name(); }

}  // namespace robot_name
```

Note: std::to_string(999) returns "999" — but to_string(123) returns "123" (3 digits), and to_string(45) returns "45" (2 digits). We need to zero-pad to 3 digits. So format with padding: use snprintf or manual formatting.

